    parallel=ident in ('ecc','sm2-encrypt','ecc-compare','hash-compare','sm4','aes-compare','protocols','engineering')
    if parallel:body='<div class="viz-three">'+''.join(node(t(a,b),t(c,d),'neutral') for a,b,c,d in items)+'</div>'
    else:body=flow([part for i,(a,b,c,d) in enumerate(items) for part in ([arrow()] if i else [])+[node(t(a,b),t(c,d),'protected' if i==len(items)-1 else 'neutral')]])
    caption=t('Original explanatory diagram; parallel boxes compare layers or roles, while arrows show conceptual data flow. Read exact equations and encodings below.','原创说明图；并列框用于比较层次或角色，箭头表示概念数据流。精确等式和编码见正文。')
    return frame(lang,'viz-'+ident,t(en,zh),body,caption,SOURCES[ref][2],SOURCES[ref][0])
